// --- WebRTC & Tool Logic ---
        const uiAwaiting = document.getElementById('ui-awaiting');
        const cameraContainer = document.getElementById('camera-container');
        const uiComplete = document.getElementById('ui-complete');
        const btnStart = document.getElementById('btn-start');
        const btnDownload = document.getElementById('btn-download');
        const progressContainer = document.getElementById('progress-container');
        const progressBar = document.getElementById('progress-bar');
        const progressStatus = document.getElementById('progress-status');
        const progressPct = document.getElementById('progress-pct');
        const video = document.getElementById('webcam-feed');
        const canvas = document.getElementById('scan-canvas');
        const overlayText = document.getElementById('scan-overlay-text');
        let stream = null;
        let animationFrameId;
        async function initializeScanner() {
            try {
                // Request Webcam
                stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "user" }, audio: false });
                video.srcObject = stream;
                // UI States
                uiAwaiting.classList.add('hidden');
                cameraContainer.style.display = 'block';
                cameraContainer.classList.add('scanning');
                btnStart.classList.add('hidden');
                progressContainer.classList.remove('hidden');
                video.onloadedmetadata = () => {
                    canvas.width = video.videoWidth;
                    canvas.height = video.videoHeight;
                    startSimulatedScan();
                };
            } catch (err) {
                console.error("Camera error:", err);
                alert("We need camera access to measure ear geometry. Please enable permissions or check your browser settings.");
            }
        }
        function startSimulatedScan() {
            const ctx = canvas.getContext('2d');
            let frameCount = 0;
            // Render Loop
            function drawOverlay() {
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                // Tech Overlay Visuals
                ctx.fillStyle = "rgba(16, 185, 129, 0.8)";
                ctx.strokeStyle = "rgba(16, 185, 129, 0.3)";
                ctx.lineWidth = 1;
                const centerX = canvas.width / 2;
                const centerY = canvas.height / 2;
                // Random tech-points
                if (frameCount % 8 === 0) {
                    ctx.beginPath();
                    for (let i = 0; i < 12; i++) {
                        const x = centerX + (Math.random() - 0.5) * 300;
                        const y = centerY + (Math.random() - 0.5) * 350;
                        ctx.moveTo(x, y);
                        ctx.arc(x, y, 2, 0, Math.PI * 2);
                    }
                    ctx.stroke();
                    ctx.fill();
                }
                frameCount++;
                animationFrameId = requestAnimationFrame(drawOverlay);
            }
            drawOverlay();
            simulateProgress();
        }
        function simulateProgress() {
            let progress = 0;
            overlayText.classList.remove('hidden');
            const phases = [
                { limit: 20, text: "Triangulating Face Mesh..." },
                { limit: 40, text: "Mapping Pinna Folds..." },
                { limit: 60, text: "Estimating Head Width (ITD)..." },
                { limit: 80, text: "Computing Harmonics..." },
                { limit: 100, text: "Finalizing JSON Matrix..." }
            ];
            let currentPhase = 0;
            const interval = setInterval(() => {
                progress += Math.random() * 2.5;
                if (progress >= 100) progress = 100;
                progressBar.style.width = `${progress}%`;
                progressPct.innerText = `${Math.floor(progress)}%`;
                if (progress >= phases[currentPhase].limit) {
                    progressStatus.innerText = phases[currentPhase].text;
                    overlayText.querySelector('span').innerText = phases[currentPhase].text;
                    if (currentPhase < phases.length - 1) currentPhase++;
                }
                if (progress >= 100) {
                    clearInterval(interval);
                    completeScan();
                }
            }, 100);
        }
        function completeScan() {
            cancelAnimationFrame(animationFrameId);
            if (stream) {
                stream.getTracks().forEach(track => track.stop());
            }
            cameraContainer.style.display = 'none';
            progressContainer.classList.add('hidden');
            uiComplete.classList.remove('hidden');
            btnDownload.classList.remove('hidden');
        }
        function downloadHRTF() {
            // Generate Random Bio-Metric Data
            const mockProfile = {
                metadata: {
                    type: "HRTF_Personalized_Profile",
                    version: "2.5",
                    timestamp: new Date().toISOString(),
                    engine: "ToolkitGen_Optical_v1"
                },
                bio_metrics: {
                    head_width_cm: (13.5 + Math.random() * 2).toFixed(2),
                    pinna_height_mm: (55 + Math.random() * 10).toFixed(1),
                    itd_max_ms: (0.0006 + Math.random() * 0.0001).toFixed(6)
                },
                parametric_eq_correction: {
                    elevation_boost_hz: [4200, 8500],
                    notch_filter_hz: [6500, 11000],
                    q_factor: 2.4
                },
                spatial_coefficients: Array.from({ length: 16 }, () => parseFloat((Math.random()).toFixed(4)))
            };
            const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(mockProfile, null, 4));
            const dlAnchorElem = document.createElement('a');
            dlAnchorElem.setAttribute("href", dataStr);
            dlAnchorElem.setAttribute("download", "My_Personalized_HRTF.json");
            document.body.appendChild(dlAnchorElem);
            dlAnchorElem.click();
            dlAnchorElem.remove();
        }
